function editRecord(type,id){let obj=type==="days"?trip().days.find(x=>x.id===id):type==="items"?trip().days.flatMap(d=>d.items).find(x=>x.id===id):trip()[type]?.find(x=>x.id===id);if(!obj)return;formFor(type,{...obj,dayId:obj.dayId});}
function deleteRecord(type,id){if(!confirmDelete("確定要刪除這筆資料嗎？此操作無法復原。"))return;let t=trip();if(type==="items"){t.days.forEach(d=>d.items=d.items.filter(x=>x.id!==id));}else if(type==="days"){t.days=t.days.filter(x=>x.id!==id);}else if(type==="expenses"){t.expenses=t.expenses.filter(x=>x.id!==id);}else t[type]=t[type].filter(x=>x.id!==id);save();render();toast("已刪除");}
function addToItinerary(kind,id){let t=trip(),src=kind==="flight"?t.flights.find(x=>x.id===id):kind==="stay"?t.accommodations.find(x=>x.id===id):t.restaurants.find(x=>x.id===id);if(!src)return;if(!t.days.length){t.days.push({id:uid("d"),date:src.date||src.checkin||new Date().toISOString().slice(0,10),region:src.region||src.to||"",theme:"",items:[]});}let day=t.days.find(d=>d.date===(src.date||src.checkin))||t.days[0];let item={id:uid("i"),time:src.departTime||"",title:src.name||[src.airline,src.number].filter(Boolean).join(" "),category:kind==="flight"?"航班":kind==="stay"?"住宿":"餐廳",note:src.note||src.address||"",transport:"",duration:"",map:src.map||"",link:src.website||"",status:"已確認",referenceId:id,referenceType:kind};day.items.push(item);save();view="section";section="itinerary";render();toast("已引用至行程");}
function addExpenseFrom(kind,id){let t=trip(),src=kind==="stay"?t.accommodations.find(x=>x.id===id):t.restaurants.find(x=>x.id===id);if(!src)return;formFor("expenses",{name:src.name,amount:src.amount||"",currency:src.currency||"TWD",rate:src.currency==="TWD"?1:19.2,category:kind==="stay"?"住宿":"餐廳",date:src.checkin||new Date().toISOString().slice(0,10),participants:t.members.map(m=>m.id)});}
